ac:PartyIdentification": {"cbc:ID": {"@schemeName": "organization", "#text": "ORG-0002"}}, "cac:ServiceProviderParty": {"cbc:ServiceTypeCode": {"@listName": "organisation-role", "#text": "ted-esen"}, "cac:Party": {"cac:PartyIdentification": {"cbc:ID": {"@schemeName": "organization", "#text": "ORG-0001"}}}}}}, "cac:ProcurementProject": {"cbc:ID": "24AS-0094-H", "cbc:Name": {"@languageID": "FRA", "#text": "Concession avec délégation de service public pour l'exploitation du centre aquatique de la communauté de communes de l'Huisne sarthoise"}, "cbc:Description": {"@languageID": "FRA", "#text": "Le Concessionnaire est responsable de la gestion complète du Service incluant la gestion et l'exploitation commerciale, administrative, financière et technique. Le Concessionnaire assure l'exploitation du Service public concédé au travers des missions suivantes :
- L'exercice des activités suivantes :
- L'organisation de la baignade publique dans les divers bassins prévus à cet effet et leurs espaces annexes intérieurs et extérieurs, praticables pendant les heures d'ouverture au grand public ;
- L'accueil des groupes (scolaires du 1er degré, scolaires du 2nd degré, clubs et associations, centres de loisirs, etc.) pendant les heures réservées à cet effet ;
- L'enseignement et la surveillance des séances pédagogiques à destination des élèves des établissements scolaires du 1er degré, pendant les périodes réservées à cet effet ;
- La surveillance des séances pédagogiques à destination des élèves des établissements scolaires du 2nd degré, pendant les périodes réservées à cet effet ;
- Le développement des activités de détente et de loisir ;
- Le développement des activités aquatiques telles que les cours de natation individuels ou collectifs, assurés directement par le personnel du concessionnaire, les activités de gymnastique aquatique ainsi que toutes autres activités liées à l'usage de l'eau ;
- L'exploitation de l'espace bien-être / fitness
- La gestion du service, des locaux et équipements mis à sa disposition, à savoir :
- La planification globale d'utilisation du site ;
- La gestion technique, administrative, financière et commerciale du Centre aquatique ;
- Le gardiennage des installations
- L'accueil des usagers : organiser et coordonner les activités sportives, ludiques et de loisirs ; surveiller les baigneurs et autres usagers de l'équipement dans les conditions réglementaires et de sécurité en vigueur ;
- L'entretien courant des locaux (intérieur et extérieur), la maintenance et la réparation des biens, équipements, installations et du matériel dans les conditions définies par le présent contrat ;
- L'animation de l'équipement (activités) et l'organisation d'événements propices à la renommée de l'équipement ;
- Le recrutement, la formation et l'encadrement du personnel du concessionnaire et du personnel détaché affecté au service ;
- Le contrôle de l'hygiène, notamment la réalisation de tous les contrôles (en interne ou externalisés) prévus par la réglementation ;
- La perception des droits d'entrée auprès des usagers conformément aux tarifs fixés par la convention de Concession de service public ;
- Assurer la gestion de la relation avec les usagers (enregistrement des réclamations, analyse et proposition de réponse, …)"}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "services"}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "92610000"}}, "cac:AdditionalCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "92610000"}}}, "cac:ProcurementProjectLot": {"cbc:ID": {"@schemeName": "Lot", "#text": "LOT-0000"}, "cac:TenderingTerms": {"cbc:FundingProgramCode": {"@listName": "eu-funded", "#text": "no-eu-funds"}, "cac:AwardingTerms": {"cac:AwardingCriterion": {"cac:SubordinateAwardingCriterion": [{"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weight", "#text": "poi-exa"}, "efbc:ParameterNumeric": "45"}}}}}, "cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "quality"}, "cbc:Description": {"@languageID": "FRA", "#text": "1. Valeur technique"}}, {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weight", "#text": "poi-exa"}, "efbc:ParameterNumeric": "40"}}}}}, "cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "cost"}, "cbc:Description": {"@languageID": "FRA", "#text": "2. Valeur économique"}}, {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weight", "#text": "poi-exa"}, "efbc:ParameterNumeric": "10"}}}}}, "cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "quality"}, "cbc:Description": {"@languageID": "FRA", "#text": "3. Engagement juridique"}}, {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"ef