Course spéciale 60016", "cbc:Department": "54", "cbc:CityName": "NANCY", "cbc:PostalZone": "54035", "cbc:CountrySubentityCode": {"@listName": "nuts", "#text": "FRF31"}, "cac:Country": {"cbc:IdentificationCode": {"@listName": "country", "#text": "FRA"}}}, "cac:PartyLegalEntity": {"cbc:CompanyID": "11000201100044"}, "cac:Contact": {"cbc:Name": "Sébastien BARCELO", "cbc:Telephone": "+33 (0)383193539", "cbc:ElectronicMail": "sebastien.barcelo@intradef.gouv.fr"}}}, {"efac:Company": {"cac:PartyIdentification": {"cbc:ID": {"@schemeName": "organization", "#text": "ORG-0002"}}, "cac:PartyName": {"cbc:Name": {"@languageID": "FRA", "#text": "Tribunal Administratif de Nancy"}}, "cac:PostalAddress": {"cbc:StreetName": "5 place de la Carrière C.O. n° 20038 ", "cbc:Department": "54", "cbc:CityName": "NANCY", "cbc:PostalZone": "54036", "cbc:CountrySubentityCode": {"@listName": "nuts", "#text": "FRF31"}, "cac:Country": {"cbc:IdentificationCode": {"@listName": "country", "#text": "FRA"}}}, "cac:PartyLegalEntity": {"cbc:CompanyID": "17540005000019"}, "cac:Contact": {"cbc:Telephone": "+33 (0)383174343", "cbc:Telefax": "+33 (0)383174350", "cbc:ElectronicMail": "greffe.ta-nancy@juradm.fr"}}}]}}}}}, "cbc:UBLVersionID": "2.3", "cbc:CustomizationID": "eforms-sdk-1.11", "cbc:ID": {"@schemeName": "notice-id", "#text": "801dabb8-c4c2-4887-914e-e8488c3879f3"}, "cbc:IssueDate": "2025-01-20+02:00", "cbc:IssueTime": "17:49:33+02:00", "cbc:VersionID": "01", "cbc:PlannedDate": "2025-03-28+02:00", "cbc:RegulatoryDomain": "32009L0081", "cbc:NoticeTypeCode": {"@listName": "planning", "#text": "pin-only"}, "cbc:NoticeLanguageCode": {"@listName": "language", "#text": "FRA"}, "cac:ContractingParty": {"cac:ContractingPartyType": {"cbc:PartyTypeCode": {"@listName": "buyer-legal-type", "#text": "cga"}}, "cac:ContractingActivity": {"cbc:ActivityTypeCode": {"@listName": "authority-activity", "#text": "defence"}}, "cac:Party": {"cac:PartyIdentification": {"cbc:ID": "ORG-0001"}}}, "cac:ProcurementProject": {"cbc:Name": {"@languageID": "FRA", "#text": "Réhabilitation et adaptation des infrastructures de l'entrepôt logistique du Service de l'énergie opérationnelle (SEO) de Portes-lès-Valence."}, "cbc:Description": {"@languageID": "FRA", "#text": "Le présent projet entre dans le champ défini par l'article L.1113-1 du Code de la commande publique (CCP) aussi, le représentant du maître d'ouvrage (RMO) est tenu de recourir à un marché passé selon les règles spécifiques applicables aux marchés de défense ou de sécurité. Considérant que le montant estimé de l'opération se situe au-delà du seuil de procédure formalisée applicable aux marchés de travaux, conformément aux dispositions de l'article R.2324-2 du CCP, la procédure mise en oeuvre sera celle de l'appel d'offres restreint. Par voie de conséquence, seuls les candidats sélectionnés à l'issue d'une phase initiale dite "de candidature" réputée apprécier la capacité économique et financière ainsi que les garanties techniques et professionnelles, seront autorisés à soumissionner à l'occasion d'une seconde phase, dite "de remise des offres". La phase de candidature fera l'objet de la parution d'un avis d'appel public à la concurrence à la date prévisionnelle mentionnée dans le présent avis, sur la base d'un unique règlement de la consultation enrichi d'une description des données utiles du programme. La phase de remise des offres prévoit la mise à disposition d'un dossier de consultation des entreprises (DCE) exhaustif. À l'échéance cumulative de ces deux phases, seront jugées les offres sur le fondement de critères d'attribution observant et jugeant la valeur technique, au moyen notamment de la production d'un mémoire technique personnalisé, conforme au plan et attendus exprimés dans le DCE mais également de l'appréciation de l'offre tarifaire. Pour ce faire, il est établi qu'une visite du site objet des travaux soit rendue obligatoire aux prémices de la phase de remise des offres ; elle s'insère dans l'objectif ambitionné de permettre la juste construction de l'offre tarifaire et une définition cohérente des solutions techniques, en permettant d'appréhender concrètement la typologie du projet, les caractéristiques du site et l'envergure des opérations à mener."}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "works"}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45000000"}}, "cac:AdditionalCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "90722100"}}, "cac:RealizedLocation": {"cbc:Description": {"@languageID": "FRA", "#text": "La notification des marchés objets des lots emportera l'acceptation des sous-contractants présentés au moyen d'une déclaration par le soumissionnaire au moment du dépôt de l'offre néanmoins, le RMO écartera le sous-contractant s'il fait l'objet d'une interdiction de soumissionner ou s'il ne présente pas les garanties suffisantes telles que celles exigées pour les candidats du marché public principal en termes de capacités techniques, professionnelles et financières ou de sécurité de l'information ou d'approvisionnement.
